// services/feedback-service.js
modules["services/feedback-service.js"] = (() => {
const showToast = (message, tone = 'success') => {
  const toastElement = document.querySelector('#site-toast');
  if (!toastElement || typeof bootstrap === 'undefined') return;
  const messageElement = toastElement.querySelector('span');
  if (messageElement) messageElement.textContent = message;
  const icon = toastElement.querySelector('i');
  if (icon) icon.className = `bi bi-${tone === 'error' ? 'exclamation-circle-fill text-danger' : 'check-circle-fill text-success'}`;
  bootstrap.Toast.getOrCreateInstance(toastElement, { delay: 3500 }).show();
};

const initializeInteractiveForms = () => {
  document.querySelectorAll('[data-interactive-form]').forEach((form) => form.addEventListener('submit', (event) => {
    event.preventDefault();
    if (!form.checkValidity()) { form.classList.add('was-validated'); return; }
    form.reset();
    form.classList.remove('was-validated');
    const modal = form.closest('.modal');
    if (modal && typeof bootstrap !== 'undefined') bootstrap.Modal.getOrCreateInstance(modal).hide();
    showToast('تم التحقق من البيانات بنجاح.');
  }));
};

const initializeContactForm = () => {
  const form = document.querySelector('#contact-form');
  const alertElement = document.querySelector('#contact-alert');
  if (!form || !alertElement) return;
  form.addEventListener('submit', (event) => {
    event.preventDefault();
    if (!form.checkValidity()) {
      form.classList.add('was-validated');
      alertElement.className = 'alert alert-danger';
      alertElement.innerHTML = '<i class="bi bi-exclamation-circle me-2"></i>يرجى تصحيح الحقول المطلوبة قبل المتابعة.';
      return;
    }
    const submitButton = form.querySelector('button[type="submit"]');
    if (submitButton) {
      submitButton.disabled = true;
      submitButton.innerHTML = '<span class="spinner-border spinner-border-sm ms-2" aria-hidden="true"></span> جارٍ التحقق...';
    }
    window.setTimeout(() => {
      if (submitButton) {
        submitButton.disabled = false;
        submitButton.innerHTML = 'إرسال الرسالة <i class="bi bi-arrow-left"></i>';
      }
      form.reset();
      form.classList.remove('was-validated');
      alertElement.className = 'alert alert-success';
      alertElement.innerHTML = '<i class="bi bi-check-circle me-2"></i>تم التحقق من بيانات الرسالة بنجاح.';
    }, 500);
  });
  form.addEventListener('reset', () => {
    form.classList.remove('was-validated');
    alertElement.className = 'alert d-none';
    alertElement.textContent = '';
  });
};

return { showToast, initializeInteractiveForms, initializeContactForm };
})();

// utils/event-dates.js
modules["utils/event-dates.js"] = (() => {
const EVENT_TIME_ZONE = 'Asia/Damascus';

const parseEventDate = (dateValue) => new Date(`${dateValue}T12:00:00Z`);

const formatEventDate = (dateValue) => new Intl.DateTimeFormat('ar-SY', {
  weekday: 'long', day: 'numeric', month: 'long', year: 'numeric', timeZone: 'UTC',
}).format(parseEventDate(dateValue));

const getDateParts = (dateValue) => {
  const date = parseEventDate(dateValue);
  return {
    day: dateValue.slice(-2),
    month: new Intl.DateTimeFormat('ar-SY', { month: 'long', timeZone: 'UTC' }).format(date),
    year: dateValue.slice(0, 4),
  };
};

const isPastEvent = (event, now = new Date()) => {
  const parts = new Intl.DateTimeFormat('en-CA', {
    timeZone: EVENT_TIME_ZONE, year: 'numeric', month: '2-digit', day: '2-digit',
    hour: '2-digit', minute: '2-digit', hourCycle: 'h23',
  }).formatToParts(now);
  const values = Object.fromEntries(parts.map(({ type, value }) => [type, value]));
  const localNow = `${values.year}-${values.month}-${values.day}T${values.hour}:${values.minute}`;
  return `${event.dateValue}T${event.time.slice(-5)}` <= localNow;
};

const getUpcomingEvents = (events, now = new Date()) => Object.entries(events)
  .filter(([, event]) => !isPastEvent(event, now))
  .sort(([, first], [, second]) => `${first.dateValue}T${first.time.slice(0, 5)}`
    .localeCompare(`${second.dateValue}T${second.time.slice(0, 5)}`));

return { formatEventDate, getDateParts, isPastEvent, getUpcomingEvents };
})();

